def evolved_p88(x, N, rank, world_size, num_devices,
                 cores_per_device, xm, torch, num_nodes=1):
    # Formula: x[i, j] = i XOR j (bitwise XOR of row/col indices).
    # Position-based, no collective. Output shape (N, N).
    idx = torch.arange(N, device=x.device, dtype=torch.int64)
    return (idx.view(N, 1) ^ idx.view(1, N)).to(x.dtype)

